<script setup lang="ts">
import { ArrowUpRight, ArrowRight, Code2, Layers3, BookOpen, CornerDownRight, Sparkles } from 'lucide-vue-next'
const { data: knowledge, error: knowledgeError, status: knowledgeStatus, refresh: refreshKnowledge } = await useFetch('/api/knowledge', { lazy: true })
const collections = computed(() => knowledge.value?.slice(0, 3) || [])
const { data: articles, error: articlesError, status: articlesStatus, refresh: refreshArticles } = await useFetch('/api/content', { lazy: true })
if (import.meta.server && (knowledgeError.value || articlesError.value)) {
  setResponseStatus(503)
  useResponseHeader('cache-control').value = 'no-store'
  useResponseHeader('cdn-cache-control').value = 'no-store'
}
const articlesLoading = computed(() => articlesStatus.value === 'idle' || articlesStatus.value === 'pending')
const knowledgeLoading = computed(() => knowledgeStatus.value === 'idle' || knowledgeStatus.value === 'pending')
const featured = computed(() => articles.value?.find(a => a.featured))
const latest = computed(() => articles.value?.filter(a => a.id !== featured.value?.id).slice(0, 4) || [])
const { data: site } = useSiteWorkspace()
usePageSeo({ title: () => site.value?.settings.seoTitle || 'XIAOJUESHI', description: () => site.value?.settings.description || 'xiaojueshi 的个人博客，分享技术实践、学习笔记与日常。', path: '/' })
</script>
<template><div><SiteHeader /><main id="main" class="shell">
  <section class="hero"><div class="hero-copy"><div class="eyebrow"><span class="status-dot" /> 开发 · 记录 · 分享 <span class="eyebrow-tail">XIAOJUESHI</span></div><h1 class="hero-title" aria-label="永远相信美好的事情即将发生"><span>永远相信</span><span>美好的事情</span><span>即将发生<span class="hero-period">。</span></span></h1><p class="hero-description">你好，我是 <strong>xiaojueshi</strong>。<br />一个程序员，喜欢 Vue 和 Bun。<br />分享技术实践，也记录日常。</p><div class="hero-actions"><NuxtLink to="/articles" class="button button-dark">开始阅读 <ArrowUpRight :size="17" /></NuxtLink><NuxtLink to="/about" class="text-link">关于我 <ArrowRight :size="16" /></NuxtLink></div></div><BrandOrbit /></section>
  <div class="intro-divider"><span>CODE / NOTES / LIFE</span><span>记录一些有意思的事 <span class="accent">↙</span></span></div>
  <section v-if="articlesLoading" class="featured-section"><div class="section-kicker"><span class="section-index">01 /</span><span>精选文章</span><span class="english-kicker">FEATURED</span></div><LoadingSkeleton variant="featured" label="正在加载精选文章" /></section>
  <section v-else-if="featured && !articlesError" class="featured-section"><div class="section-kicker"><span class="section-index">01 /</span><span>精选文章</span><span class="english-kicker">FEATURED</span></div><NuxtLink :to="`/articles/${featured.slug}`" :prefetch="false" class="featured-card"><div class="featured-copy"><div class="article-meta"><span class="featured-label"><Sparkles :size="13" /> 精选文章</span><span class="meta-dot">/</span><span>{{ featured.category }}</span></div><h2>{{ featured.title }}</h2><p>{{ featured.summary }}</p><div class="featured-bottom"><time>{{ featured.publishedAt.slice(0,10).replaceAll('-', '.') }}</time><span>阅读文章 <ArrowUpRight :size="16" /></span></div></div><div class="featured-art" aria-hidden="true"><div class="art-frame frame-one" /><div class="art-frame frame-two" /><div class="art-frame frame-three" /><span class="art-label">LESS, BUT BETTER.</span><span class="art-corner">↗</span></div></NuxtLink></section>
  <section class="latest-section"><div class="section-heading"><div class="section-kicker"><span class="section-index">02 /</span><h2>最近记录</h2><span class="english-kicker">LATEST ENTRIES</span></div><NuxtLink to="/articles" class="text-link small">全部记录 <ArrowUpRight :size="15" /></NuxtLink></div><LoadingSkeleton v-if="articlesLoading" variant="article-list" label="正在加载最近记录" /><div v-else-if="articlesError" class="empty-state" role="alert">记录加载失败。 <button class="text-link" @click="refreshArticles()">重新加载</button></div><template v-else><div class="article-list"><ArticleRow v-for="item in latest" :key="item.id" :item="item" /></div><div v-if="!latest.length" class="empty-state">暂无公开记录。</div></template></section>
  <section class="garden-section"><div class="section-heading"><div class="section-kicker"><span class="section-index">03 /</span><h2>知识库</h2><span class="english-kicker">KNOWLEDGE BASE</span></div><NuxtLink to="/garden" :prefetch="false" class="text-link small">查看知识库 <ArrowUpRight :size="15" /></NuxtLink></div><p class="section-description">按主题整理的技术笔记与学习资料。</p><LoadingSkeleton v-if="knowledgeLoading" variant="home-knowledge" label="正在加载知识库" /><div v-else-if="knowledgeError" class="empty-state" role="alert">知识库加载失败。 <button class="text-link" @click="refreshKnowledge()">重新加载</button></div><div v-else class="garden-grid"><NuxtLink v-for="(collection, index) in collections" :key="collection.id" :to="`/garden?collection=${collection.slug}`" :prefetch="false" class="garden-card"><div class="garden-top"><component :is="[Code2, Layers3, BookOpen][index]" :size="21" :stroke-width="1.5" /><ArrowUpRight :size="17" /></div><h3>{{ collection.title }}</h3><p>{{ collection.description }}</p><div class="garden-bottom"><span>{{ collection.items.length }} 篇记录</span><span class="growing-dot">持续整理中</span></div></NuxtLink></div></section>
  <section class="closing-note"><CornerDownRight :size="26" :stroke-width="1.4" /><div><h2>更多代码，在 GitHub。</h2><p>开源项目、实验，以及正在做的事。</p></div><a href="https://github.com/xiaojueshi" target="_blank" rel="noopener noreferrer" class="text-link">在 GitHub 找到我 <ArrowUpRight :size="16" /></a></section>
  <p class="demo-note">当前文章为排版与功能示例，可在工作台中替换。</p>
</main><SiteFooter /></div></template>
